INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-0cefc922-84cb-4668-b9d3-18e6f6661e35','feed-source-5496d064f90938a458c4b1eec79d4a4b',NULL,NULL,'web_query_result','不同 Runtime 怎样读同一份项目进度','查询「AI 工作台如何保存共同进度」的本地示例结果。','如果每个入口各自记状态，换一次对话就要重新解释整个项目。共同底座应保存 Goal、关系、决定和完成依据。','web_query','共同进度怎么被记住','query:shared-progress-1',NULL,'inbox','medium','["网页查询"]',NULL,'inbox',NULL,1,'2026-09-15T10:00:00.000Z','2026-09-15T10:00:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-4b60b2f9-00d3-4f03-9a0a-13fba3a00ef3','feed-source-f34498b13c742f0d0f851765e48fe4d6',NULL,NULL,'rss_entry','第一次把模糊想法收成目标树','用户要能从列表看出下一步、阻塞和完成依据。','长程任务最容易在换对话后丢失共同进度。先把模糊想法收成目标树，再决定谁做下一步。这篇文章和当前示例项目的主 Goal 直接相关。','rss','Solidot','https://example.com/posts/goal-tree-first-run','https://www.solidot.org/','inbox','medium','["RSS","产品设计"]','Solidot','inbox',NULL,1,'2026-09-16T04:25:00.000Z','2026-09-16T04:25:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
INSERT INTO "feed_items"("project_id","item_id","source_id","signal_id","signal_revision","kind","title","summary","body","source_kind","source_label","external_id","url","origin_status","priority","tags_json","author","disposition","read_at","revision","source_created_at","source_updated_at","imported_at","updated_at") VALUES('molis-work-v1-demo','feeditem-5a3f6dc4-949f-4de2-9ef2-303182a504ce','demo-gmail',NULL,NULL,'gmail_message','第一次打开项目时，默认该先看目标还是先开会话？','合作方问首页落点。决定仍在 Goals 的 DECIDE，这里只保留邮件事实。','如果两个入口同时强调，新用户会停在选择上。请产品给一个默认落点，另一个入口仍可从同一工作台到达。','gmail','Gmail · 产品反馈','demo-gmail-landing',NULL,'inbox','medium','["Gmail","产品"]','Mina <partner@example.com>','inbox',NULL,1,'2026-09-16T05:42:00.000Z','2026-09-16T05:42:00.000Z','2026-01-15T09:00:00.000Z','2026-01-15T09:00:00.000Z');
